const canvas = document.createElement('canvas');
canvas.width = 1920; canvas.height = 1080;
const ctx = canvas.getContext('2d');

// 天空渐变
const skyGrad = ctx.createLinearGradient(0,0,0,600);
skyGrad.addColorStop(0, '#87CEEB');
skyGrad.addColorStop(1, '#FFE4B5');
ctx.fillStyle = skyGrad;
ctx.fillRect(0, 0, 1920, 600);

// 草地
ctx.fillStyle = '#90EE90';
ctx.fillRect(0, 600, 1920, 480);

// 跑道
ctx.strokeStyle = '#CD5C5C';
ctx.lineWidth = 8;
ctx.strokeEllipse(960, 750, 700, 200);

// 樱花粒子
for(let i=0; i<50; i++) {
  ctx.fillStyle = '#FFB7C5';
  ctx.beginPath();
  ctx.arc(Math.random()*1920, Math.random()*600, 3+Math.random()*5, 0, Math.PI*2);
  ctx.fill();
}

// 输出 Base64
const dataURL = canvas.toDataURL('image/png');
console.log(dataURL);
```

